pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Admin adds points to token 0
        vm.prank(address(this)); // admin is this contract, but addPoints is called by _rankedBattleAddress which is also this contract
        c.addPoints(0, 100);

        // Verify initial state
        assertEq(c.fighterPoints(0), 100);
        assertEq(c.totalPoints(), 100);
        assertEq(c.isSelectionComplete(0), false);

        // Admin calls pickWinner with token 0
        // The owner of token 0 is this contract (FighterFarm is not actually deployed, but we simulate ownerOf return)
        // Since we control the contract, we can call pickWinner
        uint256[] memory winners = new uint256[](1);
        winners[0] = 0;
        // Adjust winnersPerPeriod to 1
        c.updateWinnersPerPeriod(1);

        // Attempt pickWinner – on reference it succeeds, on bug it reverts due to reversed require
        // We catch revert to avoid test failure from revert
        bool ok;
        try c.pickWinner(winners) { ok = true; } catch { ok = false; }

        // The assertion: pickWinner should succeed (reference) but bug version reverts
        assertTrue(ok);

        // Additionally, verify state after successful call
        assertEq(c.fighterPoints(0), 0);
        assertEq(c.totalPoints(), 0);
        assertEq(c.isSelectionComplete(0), true);
        assertEq(c.roundId(), 1);
    }
}

