        c.addPoints(0, 100); // reference: fighterPoints[0] = 100, bug: fighterPoints[0] = -100 underflow would revert, so we must test sequentially
        // Second call – reference adds another 50 → total 150, bug subtracts 50 → total -150 underflow revert
        // Catch second call to handle possible revert
        bool ok;
        try c.addPoints(0, 50) { ok = true; } catch { ok = false; }
        // In reference, ok = true and fighterPoints[0] = 150; in bug, ok = true only if no underflow, but bug's subtract would have underflowed on first call
        // Actually first call with += in ref, bug uses -=; if bug's first call (100) becomes fighterPoints[0] = -100 → underflow revert → ok false
        // So after first call, bug version would have reverted, so second call not reached => ok false
        // Assert that the call succeeded, which is true for reference, false for bug
        assertTrue(ok);

        // Additionally verify the final value (only if ok was true, but we can check to be explicit)
        // Note: after bug's first revert, state unchanged; but we only check that the second call succeeded.
        // For extra clarity, also check that fighterPoints[0] == 150 (reference) vs fighterPoints[0] == 0 (bug never incremented)
        // But if second call reverted, we never reach this – so the assertTrue(ok) is sufficient.
        // However, to make it an observable divergence even if bug didn't revert (e.g., if bug used unchecked?), but the bug uses -= which under normal Solidity 0.8 will revert on underflow.
        // So the test works.
    }
}

